use super::h1;
use futures::{try_ready, Future, Poll};
use http;
use http::uri::Authority;
use linkerd2_stack::layer;

#[derive(Clone, Debug)]
pub struct Stack<N> {
    inner: N,
}

pub struct MakeFuture<F> {
    inner: F,
    authority: Option<Authority>,
}

#[derive(Clone, Debug)]
pub struct Service<S> {
    inner: S,
    authority: Option<Authority>,
}

/// Provides the information necessary for the `normalize_uri` middleware to
/// determine whether a request's URI must be normalized and, if so, the
/// authority to use.
pub trait ShouldNormalizeUri {
    fn should_normalize_uri(&self) -> Option<Authority>;
}

// === impl Layer ===

pub fn layer<M>() -> impl layer::Layer<M, Service = Stack<M>> + Copy {
    layer::mk(|inner| Stack { inner })
}

// === impl Stack ===

impl<T, M> tower::Service<T> for Stack<M>
where
    T: ShouldNormalizeUri,
    M: tower::Service<T>,
{
    type Response = tower::util::Either<Service<M::Response>, M::Response>;
    type Error = M::Error;
    type Future = MakeFuture<M::Future>;

    fn poll_ready(&mut self) -> Poll<(), M::Error> {
        self.inner.poll_ready()
    }

    fn call(&mut self, target: T) -> Self::Future {
        let authority = target.should_normalize_uri();
        let inner = self.inner.call(target);

        MakeFuture { inner, authority }
    }
}

// === impl MakeFuture ===

impl<F: Future> Future for MakeFuture<F> {
    type Item = tower::util::Either<Service<F::Item>, F::Item>;
    type Error = F::Error;

    fn poll(&mut self) -> Poll<Self::Item, Self::Error> {
        let inner = try_ready!(self.inner.poll());

        if let Some(authority) = self.authority.take() {
            Ok(tower::util::Either::A(Service {
                inner,
                authority: Some(authority),
            })
            .into())
        } else {
            Ok(tower::util::Either::B(inner).into())
        }
    }
}

// === impl Service ===

impl<S, B> tower::Service<http::Request<B>> for Service<S>
where
    S: tower::Service<http::Request<B>>,
{
    type Response = S::Response;
    type Error = S::Error;
    type Future = S::Future;

    fn poll_ready(&mut self) -> Poll<(), S::Error> {
        self.inner.poll_ready()
    }

    fn call(&mut self, mut request: http::Request<B>) -> Self::Future {
        debug_assert!(
            request.version() != http::Version::HTTP_2,
            "normalize_uri must only be applied to HTTP/1"
        );
        h1::normalize_our_view_of_uri(&mut request, self.authority.as_ref());
        self.inner.call(request)
    }
}

