```rust
//! Layer to map HTTP service errors into appropriate `http::Response`s.

use crate::svc;
use futures::{Future, Poll};
use http::{header, Request, Response, StatusCode, Version};
use linkerd2_error::Error;
use linkerd2_proxy_http::HasH2Reason;
use std::marker::PhantomData;
use tracing::{debug, error, warn};

/// Layer to map HTTP service errors into appropriate `http::Response`s.
pub fn layer<B>() -> NewRespond<B>
where
    B: Default,
{
    NewRespond(PhantomData)
}

#[derive(Clone, Debug)]
pub struct NewRespond<B>(PhantomData<fn() -> B>);

impl<B> NewRespond<B>
where
    B: Default,
{
    fn new_respond<A>(&self, req: &Request<A>) -> Respond<B> {
        match req.version() {
            Version::HTTP_2 => {
                let is_grpc = req
                    .headers()
                    .get(header::CONTENT_TYPE)
                    .and_then(|v| v.to_str().ok())
                    .map(|ct| ct.starts_with("application/grpc"))
                    .unwrap_or(false);
                Respond::Http2 { is_grpc }
            }
            version => Respond::Http1(version, PhantomData),
        }
    }
}

impl<B, M> svc::Layer<M> for NewRespond<B>
where
    B: Default,
{
    type Service = Stack<B, M>;

    fn layer(&self, inner: M) -> Self::Service {
        Stack {
            marker: PhantomData,
            inner,
        }
    }
}

#[derive(Clone, Debug)]
pub struct Stack<B, M> {
    marker: PhantomData<fn() -> B>,
