//! Layer to map HTTP service errors into appropriate `http::Response`s.

use crate::svc;
use futures::{try_ready, Future, Poll};
use http::{header, Request, Response, StatusCode, Version};
use linkerd2_error::Error;
use linkerd2_proxy_http::HasH2Reason;
use std::marker::PhantomData;
use tracing::{debug, error, warn};

/// Layer to map HTTP service errors into appropriate `http::Response`s.
pub fn layer<B>() -> NewRespond<B>
where
    B: Default,
{
    NewRespond(PhantomData)
}

#[derive(Clone, Debug)]
pub struct NewRespond<B>(PhantomData<fn() -> B>);

impl<B> NewRespond<B>
where
    B: Default,
{
    fn new_respond<A>(&self, req: &Request<A>) -> Respond<B> {
        match req.version() {
            Version::HTTP_2 => {
                let is_grpc = req
                    .headers()
                    .get(header::CONTENT_TYPE)
                    .and_then(|v| v.to_str().ok())
                    .map(|ct| ct.starts_with("application/grpc"))
                    .unwrap_or(false);
                Respond::Http2 { is_grpc }
            }
            version => Respond::Http1(version, PhantomData),
        }
    }
}

impl<B, M> svc::Layer<M> for NewRespond<B>
where
    B: Default,
{
    type Service = Stack<B, M>;

    fn layer(&self, inner: M) -> Self::Service {
        Stack {
            new_respond: self.clone(),
            inner,
        }
    }
}

#[derive(Clone, Debug)]
pub struct Stack<B, M> {
    new_respond: NewRespond<B>,
    inner: M,
}

impl<T, B, M> svc::Service<T> for Stack<B, M>
where
    M: svc::Service<T>,
    B: Default,
{
    type Response = Service<B, M::Response>;
    type Error = M::Error;
    type Future = StackFuture<B, M::Future>;

    fn poll_ready(&mut self) -> Poll<(), Self::Error> {
        self.inner.poll_ready()
    }

    fn call(&mut self, target: T) -> Self::Future {
        StackFuture {
            new_respond: self.new_respond.clone(),
            inner: self.inner.call(target),
        }
    }
}

#[derive(Debug)]
pub struct StackFuture<B, F> {
    new_respond: NewRespond<B>,
    inner: F,
}

impl<B, F> Future for StackFuture<B, F>
where
    F: Future,
    B: Default,
{
    type Item = Service<B, F::Item>;
    type Error = F::Error;

    fn poll(&mut self) -> Poll<Self::Item, Self::Error> {
        let inner = try_ready!(self.inner.poll());
        let svc = Service {
            new_respond: self.new_respond.clone(),
            inner,
        };
        Ok(svc.into())
    }
}

#[derive(Clone, Debug)]
pub struct Service<B, S> {
    new_respond: NewRespond<B>,
    inner: S,
}

impl<B, S, A> svc::Service<Request<A>> for Service<B, S>
where
    S: svc::Service<Request<A>, Response = Response<B>>,
    S::Error: Into<Error>,
    B: Default,
{
    type Response = S::Response;
    type Error = Error;
    type Future = ResponseFuture<B, S::Future>;

    fn poll_ready(&mut self) -> Poll<(), Self::Error> {
        self.inner.poll_ready().map_err(Into::into)
    }

    fn call(&mut self, req: Request<A>) -> Self::Future {
        let respond = self.new_respond.new_respond(&req);
        let inner = self.inner.call(req);
        ResponseFuture { respond, inner }
    }
}

#[derive(Clone, Debug)]
pub enum Respond<B> {
    Http2 { is_grpc: bool },
    Http1(Version, PhantomData<fn() -> B>),
}

#[derive(Debug)]
pub struct ResponseFuture<B, F> {
    respond: Respond<B>,
    inner: F,
}

impl<B, F> Future for ResponseFuture<B, F>
where
    F: Future<Item = Response<B>>,
    F::Error: Into<Error>,
    B: Default,
{
    type Item = Response<B>;
    type Error = Error;

    fn poll(&mut self) -> Poll<Self::Item, Self::Error> {
        match self.inner.poll() {
            Ok(ok) => Ok(ok),
            Err(err) => {
                let err = err.into();

                if let Respond::Http2 { .. } = self.respond {
                    if err.h2_reason().is_some() {
                        debug!("propagating http2 response error: {:?}", err);
                        return Err(err);
                    }
                }

                let (version, is_grpc) = match &self.respond {
                    Respond::Http2 { is_grpc } => (Version::HTTP_2, *is_grpc),
                    Respond::Http1(version, _) => (*version, false),
                };
                let status = map_err_to_5xx(err);

                let mut builder = Response::builder().status(status).version(version);
                if is_grpc {
                    // gRPC clients only recognize responses with an
                    // `application/grpc` content-type.
                    builder = builder.header(header::CONTENT_TYPE, "application/grpc");
                }
                let response = builder
                    .header(header::CONTENT_LENGTH, "0")
                    .body(B::default())
                    .expect("app::errors response is valid");

                debug!(%status, ?version, "Handling error with HTTP response");
                Ok(response.into())
            }
        }
    }
}

fn map_err_to_5xx(e: Error) -> StatusCode {
    use crate::proxy::buffer;
    use linkerd2_router::error as router;
    use tower::load_shed::error as shed;

    if let Some(ref c) = e.downcast_ref::<router::NoCapacity>() {
        warn!("router at capacity ({})", c.0);
        http::StatusCode::SERVICE_UNAVAILABLE
    } else if let Some(_) = e.downcast_ref::<shed::Overloaded>() {
        warn!("server overloaded, max-in-flight reached");
        http::StatusCode::SERVICE_UNAVAILABLE
    } else if let Some(_) = e.downcast_ref::<buffer::Aborted>() {
        warn!("request aborted because it reached the configured dispatch deadline");
        http::StatusCode::SERVICE_UNAVAILABLE
    } else if let Some(_) = e.downcast_ref::<router::NotRecognized>() {
        error!("could not recognize request");
        http::StatusCode::BAD_GATEWAY
    } else if let Some(err) = e.downcast_ref::<StatusError>() {
        error!(%err.status, %err.message);
