use super::h1;
use futures::{future, try_ready, Future, Poll};
use http;
use http::header::{HeaderValue, TRANSFER_ENCODING};
use tracing::{debug, warn};

pub const L5D_ORIG_PROTO: &str = "l5d-orig-proto";

/// Upgrades HTTP requests from their original protocol to HTTP2.
#[derive(Clone, Debug)]
pub struct Upgrade<S> {
    inner: S,
}

/// A future for the `Upgrade` service.
///
/// The request's original protocol is stored so that the eventual response can
/// be downgraded from HTTP2 back to the request's original protocol, based on
/// the `l5d-orig-proto` header.
#[derive(Debug)]
pub struct UpgradeFuture<F> {
    version: http::Version,
    inner: F,
}

type Response = S::Response;
    type Error = S::Error;
    type Future = UpgradeFuture<S::Future>;

    fn poll_ready(&mut self) -> Poll<(), Self::Error> {
        self.inner.poll_ready()
    }

    fn call(&mut self, mut req: http::Request<A>) -> Self::Future {
        debug_assert!(
            req.version() != http::Version::HTTP_2 && !h1::wants_upgrade(&req),
            "illegal request routed to orig-proto Upgrade",
        );

        debug!("upgrading {:?} to HTTP2 with orig-proto", req.version());

        // Remember the request's original protocol so that the response can
        // be downgraded back to it.
        let version = req.version();

        // absolute-form is far less common, origin-form is the usual,
        // so only encode the extra information if it's different than
        // the normal.
        let was_absolute_form = h1::is_absolute_form(req.uri());
        if !was_absolute_form {
            // Since the version is going to set to HTTP_2, the NormalizeUri
            // middleware won't normalize the URI automatically, so it
            // needs to be done now.
            h1::normalize_our_view_of_uri(&mut req);
        }

        let val = match (version, was_absolute_form) {
            (http::Version::HTTP_11, false) => "HTTP/1.1",
            (http::Version::HTTP_11, true) => "HTTP/1.1; absolute-form",
            (http::Version::HTTP_10, false) => "HTTP/1.0",
            (http::Version::HTTP_10, true) => "HTTP/1.0; absolute-form",
            (v, _) => unreachable!("bad orig-proto version: {:?}", v),
        };
        req.headers_mut()
            .insert(L5D_ORIG_PROTO, HeaderValue::from_static(val));

        // transfer-encoding is illegal in HTTP2
        req.headers_mut().remove(TRANSFER_ENCODING);

        *req.version_mut() = http::Version::HTTP_2;

        UpgradeFuture {
            version,
            inner: self.inner.call(req),
        }
    }
}

impl<F, B> Future for UpgradeFuture<F>
where
    F: Future<Item = http::Response<B>>,
{
    type Item = http::Response<B>;
    type Error = F::Error;

    fn poll(&mut self) -> Poll<Self::Item, Self::Error> {
        let mut res = try_ready!(self.inner.poll());
        debug_assert_eq!(res.version(), http::Version::HTTP_2);

        let version = if let Some(orig_proto) = res.headers_mut().remove(L5D_ORIG_PROTO) {
            debug!("downgrading {} response: {:?}", L5D_ORIG_PROTO, orig_proto);
            if orig_proto == "HTTP/1.1" {
                http::Version::HTTP_11
            } else if orig_proto == "HTTP/1.0" {
                http::Version::HTTP_10
            } else {
                debug!("unknown {} header value: {:?}", L5D_ORIG_PROTO, orig_proto);
                self.version
            }
        } else {
            // If the inner service didn't include the `l5d-orig-proto` header,
            // then the response's version can't be derived so we assume it
            // matches the request's original protocol. Notably, this is the
            // case when the response was synthesized by this proxy (e.g. an
            // error response) rather than produced by a service that
            // understands orig-proto. The `absolute-form` marker is not
            // handled here as it only affects the request's URI, which has no
            // bearing on the response's protocol.
            self.version
        };
        *res.version_mut() = version;

        Ok(res.into())
    }
}

