#![deny(warnings, rust_2018_idioms)]

use futures::{Async, Future, Poll};
use linkerd2_error::Error;
use tower::util::{Either, Oneshot};
use tracing::trace;

/// A layer that wraps a service stack with a fallback service.
///
/// When a service made by the inner stack fails to be created (i.e. `call`
/// errors), the fallback service is used to make the service instead.
#[derive(Clone, Debug)]
pub struct FallbackLayer<F, P = fn(&Error) -> bool> {
    fallback: F,
    predicate: P,
}

/// A service that makes a service via its inner stack, falling back to another
/// stack if the inner stack fails.
pub struct Fallback<I, F, P> {
    inner: I,
    fallback: F,
    predicate: P,
}

/// The future returned from `Fallback::call`.
///
/// When the inner service's future resolves successfully, the response is
/// wrapped in `Either::A`. If the inner service's future fails with an error
/// matching the configured predicate, the fallback service is called and its
/// result is wrapped in `Either::B`.
pub enum MakeFuture<I, F, P, T>
where
    F: tower::Service<T>,
{
    /// The inner service's future is pending.
    Inner {
        inner: I,
        fallback: F,
        target: Option<T>,
        predicate: P,
    },
    /// The fallback service is being called via `Oneshot`.
    Fallback(Oneshot<F, T>),
}

// === impl FallbackLayer ===

impl<F> FallbackLayer<F> {
    /// Returns a `FallbackLayer` that always falls back on error.
    pub fn new(fallback: F) -> Self {
        let predicate: fn(&Error) -> bool = |_| true;
        Self { fallback, predicate }
    }

    /// Returns a `FallbackLayer` that falls back when the given predicate
    /// matches the error.
    pub fn with_predicate<P>(self, predicate: P) -> FallbackLayer<F, P>
    where
        P: Fn(&Error) -> bool,
    {
        FallbackLayer {
            fallback: self.fallback,
            predicate,
        }
    }

    /// Returns a `FallbackLayer` that falls back if the error or its source
    /// is of type `E`.
    pub fn on_error<E>(self) -> FallbackLayer<F, fn(&Error) -> bool>
    where
        E: std::error::Error + 'static,
    {
        self.with_predicate(|e| e.is::<E>() || e.source().map(|s| s.is::<E>()).unwrap_or(false))
    }
}

impl<F, P, I> tower::layer::Layer<I> for FallbackLayer<F, P>
where
    F: Clone,
    P: Clone,
{
    type Service = Fallback<I, F, P>;

    fn layer(&self, inner: I) -> Self::Service {
        Self::Service {
            inner,
            fallback: self.fallback.clone(),
            predicate: self.predicate.clone(),
        }
    }
}

// === impl Fallback ===

impl<I, F, P, T> tower::Service<T> for Fallback<I, F, P>
where
    I: tower::Service<T>,
    I::Error: Into<Error>,
    F: tower::Service<T> + Clone,
    F::Error: Into<Error>,
    P: Fn(&Error) -> bool + Clone,
{
    type Response = Either<I::Response, F::Response>;
    type Error = I::Error;
    type Future = MakeFuture<I::Future, F, P, T>;

