#![deny(warnings, rust_2018_idioms)]

use futures::{Async, Future, Poll};
use linkerd2_error::Error;
use tower::util::{Either, Oneshot};
use tracing::trace;

/// A fallback layer.
///
/// If the future returned by the inner service fails with an error matching a
/// given predicate, the fallback service will be called with the target.
#[derive(Clone)]
pub struct FallbackLayer<F, P = fn(&Error) -> bool> {
    fallback: F,
    predicate: P,
}

/// A service that makes a service with an inner stack, falling back to another
/// stack when the inner stack fails.
pub struct Fallback<I, F, P> {
    inner: I,
    fallback: F,
    predicate: P,
}

/// The future returned from `Fallback::call`.
///
/// The future first tries the inner service. If its future fails with an error
/// matching the predicate, the fallback service is called via `Oneshot`. The
/// result is wrapped in a `tower::util::Either`, distinguishing whether the
/// inner or fallback service produced the result.
pub struct MakeFuture<I, F, P, T>
where
    F: tower::Service<T>,
{
    state: MakeState<I, F, P, T>,
