enum MakeState<I, F, P, T>
where
    F: tower::Service<T>,
{
    /// Waiting on the inner service's future.
    Inner {
        inner: I,
        fallback: F,
        predicate: P,
        target: Option<T>,
    },
    /// Waiting on the fallback service to become ready and be called.
    Fallback(Oneshot<F, T>),
}

// === impl FallbackLayer ===

impl<F> FallbackLayer<F> {
    /// Returns a `FallbackLayer` that uses the given `fallback` service when
    /// the inner service fails to produce a result.
    pub fn new(fallback: F) -> Self {
        let predicate: fn(&Error) -> bool = |_| true;
        FallbackLayer {
            fallback,
            predicate,
        }
    }
}

impl<F, P> FallbackLayer<F, P> {
    /// Returns a `FallbackLayer` that uses the given `predicate` to determine
    /// whether to fall back.
    pub fn with_predicate<P2>(self, predicate: P2) -> FallbackLayer<F, P2>
    where
        P2: Fn(&Error) -> bool,
    {
        FallbackLayer {
            fallback: self.fallback,
            predicate,
        }
    }

    /// Returns a `FallbackLayer` that falls back if the error or its source is
    /// of type `E`.
    pub fn on_error<E>(self) -> FallbackLayer<F, fn(&Error) -> bool>
    where
        E: std::error::Error + 'static,
    {
        self.with_predicate(|e| e.is::<E>() || e.source().map(|s| s.is::<E>()).unwrap_or(false))
    }
}

impl<F, P, S> tower::layer::Layer<S> for FallbackLayer<F, P>
where
    F: Clone,
    P: Clone,
{
    type Service = Fallback<S, F, P>;

    fn layer(&self, inner: S) -> Self::Service {
        Fallback {
            inner,
            fallback: self.fallback.clone(),
            predicate: self.predicate.clone(),
        }
    }
}

impl<F: std::fmt::Debug, P> std::fmt::Debug for FallbackLayer<F, P> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("FallbackLayer")
            .field("fallback", &self.fallback)
            .finish()
    }
}

